  $('reader').addEventListener('close',()=>{
    if(readerRouteCloses){readerRouteCloses--;return;}
    if(!$('reader').open&&EntryRoute.parse(location.hash,false).kind!=='list'&&!document.querySelector('dialog[open]'))entryRouter.close();
  });
